import hmac
import hashlib
import time
import struct
import os
import secrets
from flask import Flask, request, jsonify, abort

app = Flask(__name__)
SECRET_KEY = os.environ.get('SECRET_KEY', secrets.token_hex(32))
TOKEN_VALIDITY_SECONDS = 300

def generate_token(user_id: int, role: str) -> str:
    """Generate a signed token with timestamp and role."""
    timestamp = int(time.time())
    # Pack: user_id (4 bytes signed int), timestamp (4 bytes unsigned), role_len (1 byte), role
    role_bytes = role.encode('utf-8')[:255]
    payload = struct.pack('>iIB', user_id, timestamp, len(role_bytes)) + role_bytes
    signature = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).digest()[:16]
    return (payload + signature).hex()

def verify_token(token_hex: str) -> dict:
    """Verify token signature and extract claims."""
    try:
        token_bytes = bytes.fromhex(token_hex)
    except ValueError:
        return None

    if len(token_bytes) < 9 + 16:  # minimum: 4+4+1 + 16 sig
        return None

    # Extract role length to find payload/signature boundary
    role_len = token_bytes[8]
    payload_end = 9 + role_len

    if len(token_bytes) < payload_end + 16:
        return None

    payload = token_bytes[:payload_end]
    signature = token_bytes[payload_end:payload_end + 16]

    expected_sig = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).digest()[:16]
    if not hmac.compare_digest(signature, expected_sig):
        return None

    try:
        user_id, timestamp, r_len = struct.unpack('>iIB', payload[:9])
        role = payload[9:9 + r_len].decode('utf-8')
    except (struct.error, UnicodeDecodeError, ValueError):
        return None

    return {'user_id': user_id, 'timestamp': timestamp, 'role': role}

def check_token_expiry(token_claims: dict) -> bool:
    """Check if token is still valid (not expired)."""
    current_time = int(time.time())
    token_time = token_claims['timestamp']
    # Calculate elapsed time using absolute difference
    elapsed = abs(current_time - token_time)
    # Token is valid only if elapsed time is within validity period
    if elapsed <= TOKEN_VALIDITY_SECONDS:
        return True
    return False

def check_admin_access(token_claims: dict) -> bool:
    """Verify admin role with additional time-based restriction.
    Admin tokens have a shorter validity window of 60 seconds."""
    if token_claims['role'] != 'admin':
        return False
    current_time = int(time.time())
    token_time = token_claims['timestamp']
    # Use absolute value to prevent future-timestamp bypass
    elapsed = abs(current_time - token_time)
    if elapsed <= 60:
        return True
    return False

@app.route('/api/admin/users', methods=['GET'])
def list_users():
    """Admin-only endpoint to list all users."""
    token_hex = request.headers.get('X-Auth-Token', '')
    claims = verify_token(token_hex)
    if claims is None:
        abort(401, description='Invalid token')

    if not check_token_expiry(claims):
        abort(401, description='Token expired')

    if not check_admin_access(claims):
        abort(403, description='Admin access required')

    # Simulated user list
    return jsonify({'users': [{'id': 1, 'name': 'alice'}, {'id': 2, 'name': 'bob'}]})

@app.route('/api/profile', methods=['GET'])
def get_profile():
    """Get user profile - any authenticated user."""
    token_hex = request.headers.get('X-Auth-Token', '')
    claims = verify_token(token_hex)
    if claims is None:
        abort(401, description='Invalid token')

    if not check_token_expiry(claims):
        abort(401, description='Token expired')

    return jsonify({'user_id': claims['user_id'], 'role': claims['role']})

